PBL_st.name='PBL'; 
PBL_st.lat=11.64;
PBL_st.lon=92.73;
PBL_st.alt=0000;
PBL_st.env='Coas';
PBL_st.footp='U';
%%
% data imported via the import tool from matlab
 PBL_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\PBL_2016-2026_Hour.csv", [2, Inf]);
PBL_rd_h.Properties.DimensionNames{1}='Time';
PBL_rd_h.Properties.VariableNames{2}='Ba1_A';
PBL_rd_h.Properties.VariableNames{3}='Ba2_A';
PBL_rd_h.Properties.VariableNames{4}='Ba3_A';
PBL_rd_h.Properties.VariableNames{5}='Ba4_A';
PBL_rd_h.Properties.VariableNames{6}='Ba5_A';
PBL_rd_h.Properties.VariableNames{7}='Ba6_A';
PBL_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(PBL_rd_h);
%%
PBL_rd=retime(PBL_rd_h,'daily',@nanmedian);
%%
datevec(PBL_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(PBL_rd.Time(end)) % end in 2021 February too short %[output:0c280ed0]
plotFigControl(PBL_rd,PBL_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
PBL_cal=compute_exp_D(PBL_rd,names_abs,lambdaAE7); %[output:0966e53b]
plotFigControl_cal(PBL_cal,PBL_st.name);
%%
%HOMOGENEITY

break_PBL_abs_BP=change_point_analysis_Def(PBL_rd,names_abs,0.05,'PBL','Absorption');
T_PBL_abs_BP=make_table_breakpoints_def(break_PBL_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'}
break_PBL_expA_BP=change_point_analysis_Def(PBL_cal,names_expA,0.05,'PBL','Absorption exponent');
T_PBL_expA_BP=make_table_breakpoints_def(break_PBL_expA_BP);




